import XCTest
@MainActor final class OralJourneyTests:XCTestCase {
    private func element(_ id:String,_ app:XCUIApplication)->XCUIElement{app.descendants(matching:.any).matching(identifier:id).firstMatch}
    private func tap(_ id:String,_ app:XCUIApplication){let e=element(id,app);XCTAssertTrue(e.waitForExistence(timeout:10));for _ in 0..<12 where !e.isHittable{if e.exists,e.frame.midY<app.frame.midY{app.swipeDown(velocity:.slow)}else{app.swipeUp(velocity:.slow)}};XCTAssertTrue(e.isHittable);e.tap()}
    private func shot(_ name:String,_ app:XCUIApplication){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
    private func launch(_ variant:String,target:String="es",speech:Bool=false)->XCUIApplication {
        let app=XCUIApplication();app.launchEnvironment=["PIYALI_OFFLINE_TESTS":"1","PIYALI_TEST_IDENTITY_SCOPE":UUID().uuidString,"PIYALI_HEADLINE_FIXTURE":"failure","PIYALI_PRACTICE_FIXTURE":"oral:"+variant,"PIYALI_PRACTICE_JUDGE_FIXTURE":"offered-reference","PIYALI_QUESTION_HELP_FIXTURE":"stream","PIYALI_FLASHCARD_PREPARATION_DELAY_MS":"12000"];if speech{app.launchEnvironment["PIYALI_LESSON_SPEECH_FIXTURE"]="wrong-then-reference"};app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US","-piyali.interfaceLanguage","en","-piyali.theme","light"];app.launch();handleInitialPaperPencil(app)
        let name=app.textFields["entryName"];XCTAssertTrue(name.waitForExistence(timeout:15));name.tap();name.typeText("Oral Learner");tap("entryKeyboardDone",app);tap("createAccount",app);handleInitialPaperPencil(app);XCTAssertTrue(app.buttons["startLearning"].waitForExistence(timeout:15));tap("onboardingSupport",app);tap("onboardingOption-support-en",app);tap("onboardingPractice",app);tap("onboardingOption-practice-"+target,app);tap("startLearning",app);tap("companionContinue",app);acknowledgePaperPencil(app);tap("gettingStartedGotIt",app);chooseA1Placement(app);tap("productMenu",app);tap("productModeMenu",app);tap("productMode-path",app);if !app.buttons["lessonNode-lesson-pre-a1-1-1"].exists{tap("lessonPreviousLevel",app)}
        let first=target == "es" ? app.buttons["lessonNode-lesson-pre-a1-1-1"]:app.buttons.matching(NSPredicate(format:"identifier BEGINSWITH 'lessonNode-' AND enabled == true")).firstMatch;XCTAssertTrue(first.waitForExistence(timeout:10));for _ in 0..<10 where !first.isHittable{app.swipeUp(velocity:.slow)};first.tap();tap("startLessonFromPreview",app);XCTAssertTrue(element("typedQuestionPrompt",app).waitForExistence(timeout:10));return app
    }
    private func type(_ value:String,_ app:XCUIApplication){let field=app.textFields["typedPracticeAnswer"];XCTAssertTrue(field.waitForExistence(timeout:10));field.tap();field.typeText(value);if app.buttons["practiceKeyboardDone"].exists{tap("practiceKeyboardDone",app)}}
    private func wrong(_ app:XCUIApplication){XCTAssertTrue(app.staticTexts["practiceVerdict"].waitForExistence(timeout:15));XCTAssertTrue(app.staticTexts["practiceVerdict"].label.contains("Try again"));XCTAssertFalse(app.buttons["nextTypedQuestion"].exists)}
    private func correct(_ app:XCUIApplication){XCTAssertTrue(app.buttons["nextTypedQuestion"].waitForExistence(timeout:15));XCTAssertTrue(app.staticTexts["practiceVerdict"].label.contains("+6 XP"))}
    func testSpeakingUsesOnlyRecordingAndAutomaticallyRetriesThenAwardsOnce() {
        continueAfterFailure=false
        for variant in ["speak-repeat"]{let app=launch(variant,speech:true);XCTAssertFalse(app.textFields["typedPracticeAnswer"].exists);XCTAssertFalse(app.buttons["checkTypedAnswer"].exists);XCTAssertTrue(app.staticTexts["Hola, soy Ana."].exists);tap("typedPracticeListen",app);tap("typedPracticeMicrophone",app);wrong(app);shot("Native speaking wrong \(variant)",app);tap("typedPracticeMicrophone",app);correct(app);XCTAssertFalse(app.buttons["typedPracticeMicrophone"].exists);shot("Native speaking automatic correct \(variant)",app);tap("nextTypedQuestion",app);XCTAssertTrue(app.buttons["typedPracticeHelp"].waitForExistence(timeout:10));XCTAssertFalse(app.textFields["typedPracticeAnswer"].exists);tap("typedPracticeMicrophone",app);correct(app);shot("Native grammar speaking automatic correct",app);app.terminate()}
    }
    func testFlashcardFlipRetryExplanationAutomaticCollectionAndDeckReturn() {
        continueAfterFailure=false;let app=launch("flashcard");XCTAssertFalse(app.buttons["openLessonFlashcardDeck"].exists);XCTAssertFalse(app.buttons["collectLessonFlashcard"].exists);tap("flipLessonFlashcard",app);XCTAssertTrue(app.buttons["listenLessonFlashcard"].exists);XCTAssertFalse(app.staticTexts["practiceVerdict"].exists);tap("listenLessonFlashcard",app);tap("flipLessonFlashcard",app)
        for _ in 0..<2{type("WRONG_FIXTURE",app);tap("checkTypedAnswer",app);wrong(app);XCTAssertFalse(app.textFields["typedPracticeAnswer"].exists);XCTAssertTrue(app.buttons["retryLessonFlashcard"].exists);tap("explainTypedAnswer",app);XCTAssertTrue(app.staticTexts["typedExplanation"].waitForExistence(timeout:10));shot("Native lesson flashcard incorrect and explanation",app);tap("retryLessonFlashcard",app);XCTAssertFalse(app.staticTexts["practiceVerdict"].exists)}
        type("Hola",app);tap("checkTypedAnswer",app);correct(app);XCTAssertFalse(app.buttons["openLessonFlashcardDeck"].exists);shot("Native active collected flashcard without deck strip",app)
        tap("nextTypedQuestion",app);type("Hola",app);tap("checkTypedAnswer",app);correct(app);tap("nextTypedQuestion",app)
        XCTAssertTrue(element("lessonFlashcardGenerating",app).waitForExistence(timeout:5));XCTAssertFalse(app.buttons["checkTypedAnswer"].exists);shot("Native generating flashcard with collected deck below",app)
        tap("openLessonFlashcardDeck",app);let review=app.buttons["reviewLessonFlashcard"];XCTAssertTrue(review.waitForExistence(timeout:10));XCTAssertTrue(review.label.contains("Hello"));review.tap();XCTAssertTrue(review.label.contains("Hola"));XCTAssertFalse(app.buttons["previousLessonFlashcard"].isEnabled);XCTAssertFalse(app.buttons["nextLessonFlashcard"].isEnabled);shot("Native deck review during generation",app);tap("closeLessonFlashcardDeck",app)
        XCTAssertTrue(app.textFields["typedPracticeAnswer"].waitForExistence(timeout:15));XCTAssertFalse(app.buttons["openLessonFlashcardDeck"].exists);XCTAssertFalse(app.staticTexts["practiceVerdict"].exists)
        type("Hola",app);tap("checkTypedAnswer",app);correct(app);tap("nextTypedQuestion",app);XCTAssertTrue(app.textFields["typedPracticeAnswer"].waitForExistence(timeout:15));type("Hola",app);tap("checkTypedAnswer",app);correct(app);tap("nextTypedQuestion",app)
        tap("openLessonFlashcardDeck",app);XCTAssertTrue(app.staticTexts["1 / 2"].waitForExistence(timeout:5));tap("previousLessonFlashcard",app);XCTAssertTrue(app.staticTexts["2 / 2"].exists);tap("nextLessonFlashcard",app);XCTAssertTrue(app.staticTexts["1 / 2"].exists);shot("Native cyclic deck while next card prepares",app);tap("closeLessonFlashcardDeck",app);XCTAssertTrue(app.textFields["typedPracticeAnswer"].waitForExistence(timeout:15));XCTAssertFalse(app.staticTexts["practiceVerdict"].exists)

    }
    func testFlashcardSpeechGradesAutomaticallyAndJapaneseKeyboardEditsWithoutCredit() {
        continueAfterFailure=false;let app=launch("flashcard",speech:true);tap("typedPracticeMicrophone",app);wrong(app);tap("retryLessonFlashcard",app);tap("typedPracticeMicrophone",app);correct(app);shot("Native spoken lesson flashcard collected",app);app.terminate()
        let japanese=launch("flashcard-ja",target:"ja");tap("lessonFlashcardKeyboardToggle",japanese);tap("writingKey-0-0",japanese);XCTAssertEqual(japanese.textFields["typedPracticeAnswer"].value as? String,"あ");tap("writingKeyboardKatakana",japanese);tap("writingKey-0-0",japanese);XCTAssertEqual(japanese.textFields["typedPracticeAnswer"].value as? String,"あア");tap("writingKeyboardSpace",japanese);tap("writingKeyboardBackspace",japanese);tap("writingKeyboardBackspace",japanese);XCTAssertEqual(japanese.textFields["typedPracticeAnswer"].value as? String,"あ");shot("Native Japanese lesson flashcard keyboard",japanese);tap("writingKeyboardClose",japanese);XCTAssertFalse(japanese.otherElements["writingVirtualKeyboard"].exists);XCTAssertFalse(japanese.staticTexts["practiceVerdict"].exists)
    }
}
